export const PKG_VITE_CONFIG = "import { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\n// Standard Vite React setup, with one deliberate addition: `xlsx` (SheetJS)\n// ships as a CommonJS package, and Vite's dependency pre-bundler can\n// sometimes fail to resolve its internal requires correctly on the first\n// cold build, especially right after a fresh `npm install` before Vite has\n// cached its dependency scan. Explicitly listing it in optimizeDeps.include\n// forces Vite to pre-bundle it up front rather than discover it lazily,\n// which avoids that class of \"module not found\" error during `npm run dev`\n// or `npm run build`. If you ever add more CJS-only packages, list them here\n// too rather than relying on Vite's automatic detection.\nexport default defineConfig({\n  plugins: [react()],\n  server: { port: 5173 },\n  build: { outDir: \"dist\", sourcemap: false },\n  optimizeDeps: { include: [\"xlsx\"] },\n});\n";
